"""Render repository-maintained message templates in the NotifyHub layout."""

from jinja2 import Template

LAYOUT = "To: {recipient}\n\n{body}\n\n\u2014 Sent with NotifyHub"


def render_message(recipient: str, body: str) -> str:
    rendered_body = Template(body).render(recipient=recipient)
    return LAYOUT.format(recipient=recipient, body=rendered_body)
